#!/usr/bin/env python3
"""Generate the CameraParameters constants shim for the stock camera HAL.  UNBUILT / UNTESTED output.

The stock camera HAL (camera.mrvl.so) imports constants such as CameraParameters::KEY_CONTRAST from the stock
libcamera_client.so.  Android 7 no longer defines 25 of them. This tool reads their values from a libcamera_client.so
and writes C++ definitions with the exact mangled names.

IMPORTANT: run it only against files extracted from VERIFIED OFFICIAL firmware (see android/vendor/.../README.md).
Do NOT run it against the rooted community dump and commit the result. The output is not part of the repository
(it is git-ignored) for that reason.

Usage (needs: pip install pyelftools; binutils c++filt):
  python3 -I gen-camera-shim.py --camera-hal camera.mrvl.so --client-lib libcamera_client.so \
      --n7-source frameworks/av/camera/CameraParameters.cpp --out camera_params_generated.cpp
"""
import argparse, re, subprocess, sys
from elftools.elf.elffile import ELFFile

ap = argparse.ArgumentParser()
ap.add_argument('--camera-hal', required=True)
ap.add_argument('--client-lib', required=True)
ap.add_argument('--n7-source', required=True, help="cm-14.1 frameworks/av/camera/CameraParameters.cpp")
ap.add_argument('--out', required=True)
a = ap.parse_args()

def dynsyms(path):
    f = open(path, 'rb'); e = ELFFile(f)
    return f, e, e.get_section_by_name('.dynsym')

f, e, ds = dynsyms(a.camera_hal)
undef = [s.name for s in ds.iter_symbols() if s.name and s['st_shndx'] == 'SHN_UNDEF'
         and s.name.startswith('_ZN7android16CameraParameters')]
dem = subprocess.run(['c++filt'], input='\n'.join(undef), capture_output=True, text=True).stdout.split('\n')
n7 = open(a.n7_source, errors='replace').read()
missing = []
for mangled, d in zip(undef, dem):
    if '(' in d:          # member functions are not constants
        continue
    key = d.split('::')[-1]
    if not re.search(r'CameraParameters::' + re.escape(key) + r'\b', n7):
        missing.append((mangled, key))

cf, ce, cds = dynsyms(a.client_lib)
defs = {s.name: s for s in cds.iter_symbols() if s.name and s['st_shndx'] != 'SHN_UNDEF'}

def read(va, n):
    for seg in ce.iter_segments():
        if seg['p_type'] == 'PT_LOAD' and seg['p_vaddr'] <= va < seg['p_vaddr'] + seg['p_filesz']:
            cf.seek(va - seg['p_vaddr'] + seg['p_offset']); return cf.read(n)

lines = ['// GENERATED by tools/vendor/gen-camera-shim.py - do not edit, do not commit.',
         '// Values were read from: ' + a.client_lib, '']
bad = []
for i, (mangled, key) in enumerate(missing):
    s = defs.get(mangled)
    if not s:
        bad.append(key + ' (not defined in client lib)'); continue
    raw = read(s['st_value'], s['st_size'] or 64) or b''
    val = raw.split(b'\0')[0]
    if not val or not all(32 <= c < 127 for c in val) or b'"' in val or b'\\' in val:
        bad.append(key + ' (unusual value %r)' % val); continue
    lines.append('extern "C" const char goldenvess3g_cp_%d[] __asm__("%s") = "%s";  // %s'
                 % (i, mangled, val.decode(), key))
open(a.out, 'w').write('\n'.join(lines) + '\n')
print('constants needed:', len(missing), '| written:', len(lines) - 3, '| problems:', bad)
sys.exit(1 if bad else 0)
